    "CREATE FUNCTION public.protect_work_forecast_current() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $work_forecast$\nBEGIN\n IF TG_OP='INSERT' AND NEW.revision=1 THEN RETURN NEW;\n ELSIF TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['version_id','revision']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['version_id','revision'])\n  AND NEW.revision=OLD.revision+1 AND EXISTS(SELECT 1 FROM public.work_forecast_refreshes v WHERE v.tenant_id=NEW.tenant_id\n   AND v.id=NEW.version_id AND v.revision=NEW.revision AND v.previous_id=OLD.version_id AND v.previous_revision=OLD.revision) THEN RETURN NEW;\n END IF;\n RAISE EXCEPTION 'work_forecast_currents requires one exact Current CAS' USING ERRCODE='23514';\nEND\n$work_forecast$",
